import XCTest
@testable import Screener

/// Clipboard (Task 17) against `clipboard.json` (generated by calling the
/// reference's clipboard.build_* / parse_* functions), plus the sync logic.
final class ClipboardTests: XCTestCase {
    private var f: [String: Any] = [:]
    private var fixtureText: String { (f["args"] as! [String: Any])["text"] as! String }
    private var roundtrip: [String: Any] { f["roundtrip"] as! [String: Any] }

    override func setUpWithError() throws { f = try Fixture.load("clipboard") }

    // MARK: builders == fixture

    func testBuildersMatchFixture() throws {
        XCTAssertEqual(Clipboard.autoPasteboard().hex, f["build_auto_pasteboard_msg"] as! String)
        XCTAssertEqual(Clipboard.request().hex, f["build_clipboard_request"] as! String)
        XCTAssertEqual(Clipboard.request().count, 8, "9 bytes desyncs the daemon")
        XCTAssertEqual(try Clipboard.send(text: fixtureText).hex, f["build_clipboard_send"] as! String)
        XCTAssertEqual(Clipboard.archive(text: fixtureText).hex, roundtrip["decompressed"] as! String)
    }

    func testFixtureRoundTrip() throws {
        let full = Data(hex: f["build_clipboard_send"] as! String)
        var parser = ServerMessageParser()
        var r = ClipboardReassembler()
        var out: ClipboardReassembler.Output?
        for e in try parser.feed(full) {
            if case .clipboard(let h, let c) = e { out = r.feed(header: h, chunk: c) }
        }
        guard case .complete(let header, let payload)? = out else { return XCTFail("incomplete: \(String(describing: out))") }
        let hdr = roundtrip["header"] as! [String: Int]
        XCTAssertEqual(Int(header.promise), hdr["promise"])
        XCTAssertEqual(Int(header.reserved), hdr["reserved"])
        XCTAssertEqual(Int(header.uncompressedSize), hdr["uncompressed_size"])
        XCTAssertEqual(Int(header.compressedSize), hdr["compressed_size"])
        let archive = try Clipboard.inflate(payload)
        XCTAssertEqual(archive.hex, roundtrip["decompressed"] as! String)
        let items = try Clipboard.parseItems(archive)
        let expected = (roundtrip["items"] as! [[String: Any]]).map {
            ClipboardItem(primaryUTI: $0["primary_uti"] as! String, primaryData: Data(hex: $0["primary_data"] as! String))
        }
        XCTAssertEqual(items, expected)
        XCTAssertEqual(Clipboard.text(from: items), fixtureText)
        XCTAssertEqual(try Clipboard.decodeText(header: header, payload: payload), fixtureText)
    }

    // MARK: reassembly

    func testReassemblerAcrossRecords() throws {
        let full = Data(hex: f["build_clipboard_send"] as! String)
        var parser = ServerMessageParser()
        var r = ClipboardReassembler()
        var outputs: [ClipboardReassembler.Output?] = []
        // Header record, then continuation records with no header of their own.
        for range in [0..<20, 20..<41, 41..<full.count] {
            for e in try parser.feed(Data(full[range])) {
                guard case .clipboard(let h, let c) = e else { return XCTFail("unexpected \(e)") }
                outputs.append(r.feed(header: h, chunk: c))
                if range.upperBound < full.count { XCTAssertTrue(r.inProgress) }
            }
        }
        XCTAssertEqual(outputs.dropLast().compactMap { $0 }, [])
        guard case .complete(let h, let payload)?? = outputs.last else { return XCTFail() }
        XCTAssertEqual(payload, Data(full.dropFirst(16)))
        XCTAssertFalse(r.inProgress)
        XCTAssertEqual(try Clipboard.decodeText(header: h, payload: payload), fixtureText)
        // The next message starts clean.
        XCTAssertEqual(try parser.feed(Data(hex: "1400000400010002")), [.miscStatus(cmd: 2)])
    }

    func testReassemblerOversizedIsCountedThroughAndDropped() {
        var r = ClipboardReassembler(limit: 10)
        let h = ClipboardSendHeader(promise: 0, reserved: 0, uncompressedSize: 50, compressedSize: 12)
        XCTAssertNil(r.feed(header: h, chunk: Data(count: 6)))
        XCTAssertEqual(r.feed(header: h, chunk: Data(count: 6)), .oversized(12))
        let small = ClipboardSendHeader(promise: 0, reserved: 0, uncompressedSize: 5, compressedSize: 3)
        XCTAssertEqual(r.feed(header: small, chunk: Data([1, 2, 3])), .complete(small, Data([1, 2, 3])))
    }

    // MARK: empty clipboard (RFC §8.2.1)

    func testEmptyClipboardHasNoItems() throws {
        let emptyStream = try Zlib.Deflater().compress(Data())   // the daemon's short empty stream
        XCTAssertLessThanOrEqual(emptyStream.count, 7)
        let header = ClipboardSendHeader(promise: 0, reserved: 0, uncompressedSize: 0,
                                         compressedSize: UInt32(emptyStream.count))
        var w = ByteWriter()
        w.u8(0x1f); w.zeros(3); w.u32(0); w.u32(0); w.u32(UInt32(emptyStream.count)); w.bytes(emptyStream)
        var parser = ServerMessageParser()
        var r = ClipboardReassembler()
        var out: ClipboardReassembler.Output?
        for e in try parser.feed(w.data) {
            if case .clipboard(let h, let c) = e { out = r.feed(header: h, chunk: c) }
        }
        XCTAssertEqual(out, .complete(header, emptyStream))
        XCTAssertEqual(try Clipboard.parseItems(try Clipboard.inflate(emptyStream)), [])
        XCTAssertNil(try Clipboard.decodeText(header: header, payload: emptyStream))
        // compressed_size = 0: complete at once with no payload.
        let zero = ClipboardSendHeader(promise: 0, reserved: 0, uncompressedSize: 0, compressedSize: 0)
        var r2 = ClipboardReassembler()
        XCTAssertEqual(r2.feed(header: zero, chunk: Data()), .complete(zero, Data()))
        XCTAssertEqual(try Clipboard.parseItems(Data()), [])
        XCTAssertEqual(try Clipboard.parseItems(Data([0, 0])), [])
    }

    func testTruncatedArchiveThrows() {
        var archive = Clipboard.archive(text: "hello")
        archive.removeLast(2)
        XCTAssertThrowsError(try Clipboard.parseItems(archive)) { XCTAssertEqual($0 as? ClipboardError, .malformed) }
    }

    // MARK: text extraction

    private func archive(_ items: [(String, Data, [(String, Data)])]) -> Data {
        var w = ByteWriter()
        w.u32(UInt32(items.count))
        for (uti, data, aliases) in items {
            w.u32(UInt32(uti.utf8.count)); w.bytes(Data(uti.utf8)); w.u32(0)
            w.u32(UInt32(aliases.count))
            for (n, v) in aliases { w.u32(UInt32(n.utf8.count)); w.bytes(Data(n.utf8)); w.u32(UInt32(v.count)); w.bytes(v) }
            w.u32(UInt32(data.count)); w.bytes(data)
        }
        return w.data
    }

    private func utf16BE(_ s: String) -> Data { Data(s.utf16.flatMap { [UInt8($0 >> 8), UInt8($0 & 0xFF)] }) }

    func testTextPrefersUTF8ThenUTF16BigEndianThenLegacy() throws {
        // The Mac's 3-flavor pasteboard (RFC §8.2.1), UTF-16 first on the wire.
        let a = archive([
            ("public.utf16-plain-text", utf16BE("wrong"), []),
            ("com.apple.traditional-mac-plain-text", Data("legacy".utf8), [("com.apple.ostype", Data("TEXT".utf8))]),
            ("public.utf8-plain-text", Data("right ✓".utf8), [("com.apple.ostype", Data("utf8".utf8)),
                                                             ("public.mime-type", Data("text/plain;charset=utf-8".utf8))]),
        ])
        let items = try Clipboard.parseItems(a)
        XCTAssertEqual(items.count, 3)
        XCTAssertEqual(items[2].aliases.map(\.name), ["com.apple.ostype", "public.mime-type"])
        XCTAssertEqual(Clipboard.text(from: items), "right ✓")

        let utf16Only = try Clipboard.parseItems(archive([("public.utf16-plain-text", utf16BE("héllo 👋"), [])]))
        XCTAssertEqual(Clipboard.text(from: utf16Only), "héllo 👋")
        let external = try Clipboard.parseItems(archive([("public.utf16-external-plain-text",
                                                          Data([0xFE, 0xFF]) + utf16BE("ext"), [])]))
        XCTAssertEqual(Clipboard.text(from: external), "ext")
        let bomLE = Data([0xFF, 0xFE]) + Data("le".utf16.flatMap { [UInt8($0 & 0xFF), UInt8($0 >> 8)] })
        XCTAssertEqual(Clipboard.utf16(bomLE), "le")

        let legacy = try Clipboard.parseItems(archive([("public.png", Data([1, 2]), []),
                                                       ("com.apple.traditional-mac-plain-text", Data([0x63, 0x61, 0x66, 0xE9]), [])]))
        XCTAssertEqual(Clipboard.text(from: legacy), "café")
        XCTAssertNil(Clipboard.text(from: try Clipboard.parseItems(archive([("public.png", Data([1]), [])]))))
    }

    // MARK: Unicode + caps

    func testUnicodeRoundTrip() throws {
        let text = "Zürich — 東京 — مرحبا — 👩‍👩‍👧‍👦 e\u{301} 𝄞\nline 2\ttab"
        let msg = try Clipboard.send(text: text)
        var parser = ServerMessageParser()
        var r = ClipboardReassembler()
        var out: ClipboardReassembler.Output?
        for e in try parser.feed(msg) {
            if case .clipboard(let h, let c) = e { out = r.feed(header: h, chunk: c) }
        }
        guard case .complete(let h, let payload)? = out else { return XCTFail() }
        XCTAssertEqual(Int(h.uncompressedSize), Clipboard.archive(text: text).count)
        XCTAssertEqual(try Clipboard.decodeText(header: h, payload: payload), text)
    }

    func testOutboundCaps() throws {
        XCTAssertThrowsError(try Clipboard.send(text: String(repeating: "a", count: Clipboard.maxTextBytes + 1)))
        // Compressible text far over one record's raw size still fits.
        XCTAssertNoThrow(try Clipboard.send(text: String(repeating: "abc ", count: 200_000)))
        // Incompressible text that can't fit in one record is refused, not trapped on.
        var rng = SystemRandomNumberGenerator()
        let noise = String((0..<100_000).map { _ in Character(Unicode.Scalar(UInt8.random(in: 0x21...0x7E, using: &rng))) })
        XCTAssertThrowsError(try Clipboard.send(text: noise)) {
            guard case ClipboardError.tooLarge = $0 else { return XCTFail("\($0)") }
        }
        // The largest message we allow seals into one record and opens again.
        let key = Data(repeating: 0x11, count: 16)
        let blob = Data(repeating: 0x22, count: 36)
        let tx = try RecordLayer(rekeyBody: blob, wrapKey: key)
        let rx = try RecordLayer(rekeyBody: blob, wrapKey: key)
        let body = Data(repeating: 0x5A, count: Clipboard.maxOutboundMessage)
        let sealed = try tx.seal(body)
        XCTAssertEqual(try rx.open(ciphertext: Data(sealed.dropFirst(2))), body)
    }

    func testInflateLimit() throws {
        let bomb = try Zlib.Deflater().compress(Data(count: 2 << 20))
        XCTAssertThrowsError(try Clipboard.inflate(bomb, limit: 1 << 20)) {
            guard case ClipboardError.tooLarge = $0 else { return XCTFail("\($0)") }
        }
        XCTAssertEqual(try Clipboard.inflate(bomb).count, 2 << 20)
    }

    // MARK: echo-loop prevention (pure)

    func testSyncStateFirstSessionFetchesMacAndIgnoresPreexistingIPadText() {
        var s = ClipboardSyncState()
        XCTAssertEqual(s.sessionStarted(changeCount: 7), .fetchMac)
        XCTAssertFalse(s.localChanged(changeCount: 7))
        XCTAssertTrue(s.localChanged(changeCount: 8))
    }

    func testSyncStateMacTextIsNotEchoedBack() {
        var s = ClipboardSyncState()
        _ = s.sessionStarted(changeCount: 1)
        XCTAssertTrue(s.remoteText("from mac", changeCount: 1))
        s.didWriteLocal("from mac", changeCount: 2)
        // Our own write bumped changeCount; nothing to read or send.
        XCTAssertFalse(s.localChanged(changeCount: 2))
        // The same text again (e.g. another cmd=2 for it): no rewrite.
        XCTAssertFalse(s.remoteText("from mac", changeCount: 2))
        XCTAssertFalse(s.remoteText("from mac\r\n", changeCount: 2), "normalised like the reference's _norm")
        // If the iPad was read back with the same text, it isn't sent back.
        XCTAssertNil(s.localRead("from mac", changeCount: 3))
    }

    func testSyncStateIPadTextIsSentOnceAndItsEchoIsNotWritten() {
        var s = ClipboardSyncState()
        _ = s.sessionStarted(changeCount: 1)
        XCTAssertTrue(s.localChanged(changeCount: 2))
        XCTAssertEqual(s.localRead("from ipad", changeCount: 2), "from ipad")
        XCTAssertFalse(s.localChanged(changeCount: 2), "read once per change: no repeated paste prompts")
        // The Mac reports the change and we fetch our own text back.
        XCTAssertFalse(s.remoteText("from ipad", changeCount: 2))
        // The user copies the same text again on the iPad: the Mac has it.
        XCTAssertNil(s.localRead("from ipad", changeCount: 3))
        // ...unless they explicitly send it.
        XCTAssertEqual(s.localRead("from ipad", changeCount: 3, force: true), "from ipad")
    }

    func testSyncStateNewMacTextWinsOverAnUnchangedIPad() {
        var s = ClipboardSyncState()
        _ = s.sessionStarted(changeCount: 1)
        _ = s.localRead("a", changeCount: 2)
        XCTAssertTrue(s.remoteText("b", changeCount: 2))
        // Same text as the iPad has, but the iPad changed since we knew: write.
        XCTAssertTrue(s.remoteText("a", changeCount: 5))
    }

    func testSyncStateRefusedOrEmptyPasteIsNotRetriedUntilTheNextChange() {
        var s = ClipboardSyncState()
        _ = s.sessionStarted(changeCount: 1)
        XCTAssertNil(s.localRead(nil, changeCount: 2))
        XCTAssertFalse(s.localChanged(changeCount: 2))
        s.noteLocal(changeCount: 3)
        XCTAssertFalse(s.localChanged(changeCount: 3))
    }

    func testSyncStateReconnectPushesAnIPadChangeMadeWhileAway() {
        var s = ClipboardSyncState()
        _ = s.sessionStarted(changeCount: 1)
        _ = s.remoteText("mac", changeCount: 1)
        s.didWriteLocal("mac", changeCount: 2)
        XCTAssertEqual(s.sessionStarted(changeCount: 2), .fetchMac)
        XCTAssertEqual(s.sessionStarted(changeCount: 4), .pushLocal)
        // The Mac's text is unknown in a new session, so even the old text is sent.
        XCTAssertEqual(s.localRead("mac", changeCount: 4), "mac")
    }
}

// MARK: - ClipboardBridge over a fake pasteboard

@MainActor
private final class FakePasteboard: PasteboardAccess {
    var changeCount = 0
    var stored: String?
    var hasImageOnly = false
    private(set) var reads = 0
    var hasStrings: Bool { stored != nil && !hasImageOnly }
    var string: String? {
        get { reads += 1; return stored }
        set { stored = newValue; changeCount += 1 }
    }
    func userCopied(_ s: String) { stored = s; changeCount += 1 }
}

@MainActor
final class ClipboardBridgeTests: XCTestCase {
    private final class Wire: @unchecked Sendable {
        private let lock = NSLock()
        private var _sent: [Data] = []
        var sent: [Data] { lock.lock(); defer { lock.unlock() }; return _sent }
        func append(_ d: Data) { lock.lock(); _sent.append(d); lock.unlock() }
        var types: [UInt8] { sent.map { $0[0] } }
    }

    private var pb: FakePasteboard!
    private var bridge: ClipboardBridge!
    private var wire: Wire!
    private var mode = ClipboardSyncMode.automatic

    override func setUp() async throws {
        pb = FakePasteboard()
        bridge = ClipboardBridge(pasteboard: pb, observeChanges: false)
        bridge.mode = { [unowned self] in self.mode }
        wire = Wire()
    }

    private func start() async {
        let w = wire!
        bridge.start(send: { w.append($0) })
        await bridge.flush()
    }

    /// Feeds a Mac 0x1f carrying `text` and waits for the off-main decode.
    private func receive(_ text: String) async throws {
        let msg = try Clipboard.send(text: text)
        var parser = ServerMessageParser()
        for e in try parser.feed(msg) { bridge.handle(e) }
        for _ in 0..<200 {
            try await Task.sleep(for: .milliseconds(5))
            if pb.stored == text { return }
        }
    }

    private func sentText(_ d: Data) throws -> String? {
        var parser = ServerMessageParser()
        var r = ClipboardReassembler()
        for e in try parser.feed(d) {
            if case .clipboard(let h, let c) = e, case .complete(let h2, let p)? = r.feed(header: h, chunk: c) {
                return try Clipboard.decodeText(header: h2, payload: p)
            }
        }
        return nil
    }

    func testStartEnablesAutoPasteboardThenPrimes() async {
        await start()
        XCTAssertEqual(wire.types, [0x15, 0x0b])
        XCTAssertEqual(wire.sent[0], Clipboard.autoPasteboard())
        XCTAssertEqual(pb.reads, 0, "no paste prompt at connect")
    }

    func testMacChangeFetchesAndWritesOnce() async throws {
        await start()
        bridge.handle(.miscStatus(cmd: 12))
        bridge.handle(.miscStatus(cmd: 2))
        await bridge.flush()
        XCTAssertEqual(wire.types, [0x15, 0x0b, 0x0b])
        try await receive("hello-from-mac")
        XCTAssertEqual(pb.stored, "hello-from-mac")
        let count = pb.changeCount
        // Becoming active after our own write: nothing read, nothing sent.
        bridge.appBecameActive()
        await bridge.flush()
        XCTAssertEqual(pb.reads, 0)
        XCTAssertEqual(wire.sent.count, 3)
        // The same text again isn't rewritten.
        try await receive("hello-from-mac")
        try await Task.sleep(for: .milliseconds(50))
        XCTAssertEqual(pb.changeCount, count)
    }

    func testIPadCopyIsSentOnceAndNotEchoed() async throws {
        await start()
        pb.userCopied("from ipad ✓")
        bridge.appBecameActive()
        await bridge.flush()
        XCTAssertEqual(wire.types, [0x15, 0x0b, 0x1f])
        XCTAssertEqual(try sentText(wire.sent[2]), "from ipad ✓")
        XCTAssertEqual(pb.reads, 1)
        bridge.appBecameActive()
        await bridge.flush()
        XCTAssertEqual(pb.reads, 1, "unchanged changeCount: no second read")
        XCTAssertEqual(wire.sent.count, 3)
        // The Mac echoes it back: not rewritten on the iPad.
        let count = pb.changeCount
        try await receive("from ipad ✓")
        try await Task.sleep(for: .milliseconds(50))
        XCTAssertEqual(pb.changeCount, count)
    }

    func testNonTextCopyIsNotRead() async {
        await start()
        pb.userCopied("x"); pb.hasImageOnly = true
        bridge.appBecameActive()
        await bridge.flush()
        XCTAssertEqual(pb.reads, 0)
        XCTAssertEqual(wire.sent.count, 2)
    }

    func testReconnectAfterIPadCopyPushesInsteadOfPriming() async throws {
        await start()
        bridge.stop()
        pb.userCopied("copied while away")
        wire = Wire()
        await start()
        XCTAssertEqual(wire.types, [0x15, 0x1f])
        XCTAssertEqual(try sentText(wire.sent[1]), "copied while away")
    }

    func testManualModeOnlySyncsOnRequest() async throws {
        mode = .manual
        await start()
        XCTAssertEqual(wire.types, [0x15])
        bridge.handle(.miscStatus(cmd: 2))
        pb.userCopied("local")
        bridge.appBecameActive()
        await bridge.flush()
        XCTAssertEqual(wire.types, [0x15])
        XCTAssertEqual(pb.reads, 0)
        // An unsolicited 0x1f is ignored...
        try await receive("unsolicited")
        XCTAssertEqual(pb.stored, "local")
        // ...a requested one is applied.
        bridge.fetchFromMac()
        await bridge.flush()
        XCTAssertEqual(wire.types, [0x15, 0x0b])
        try await receive("requested")
        XCTAssertEqual(pb.stored, "requested")
        // Send Clipboard sends even unchanged text.
        XCTAssertTrue(bridge.sendToMac())
        await bridge.flush()
        XCTAssertEqual(wire.types, [0x15, 0x0b, 0x1f])
        XCTAssertEqual(try sentText(wire.sent[2]), "requested")
    }

    func testManualGetAnsweredByEmptyClipboardDoesNotArmTheNextMessage() async throws {
        mode = .manual
        await start()
        pb.userCopied("local")
        bridge.fetchFromMac()
        let empty = try Zlib.Deflater().compress(Data())
        var w = ByteWriter()
        w.u8(0x1f); w.zeros(3); w.u32(0); w.u32(0); w.u32(UInt32(empty.count)); w.bytes(empty)
        var parser = ServerMessageParser()
        for e in try parser.feed(w.data) { bridge.handle(e) }
        try await Task.sleep(for: .milliseconds(100))
        try await receive("unsolicited")
        XCTAssertEqual(pb.stored, "local")
    }

    func testStoppedBridgeSendsNothing() async {
        await start()
        bridge.stop()
        bridge.handle(.miscStatus(cmd: 2))
        XCTAssertFalse(bridge.sendToMac())
        bridge.fetchFromMac()
        await bridge.flush()
        XCTAssertEqual(wire.sent.count, 2)
    }
}
